// ADD ALL YOUR OTHER DISTRICT POLYGONS HERE
// var district2_plot1 = ee.Geometry.Polygon(...);
// var district3_plot1 = ee.Geometry.Polygon(...);
// etc.

// Your district names based on folder structure
var districtNames = ['hoshiarpur'
];

// Build districts array - each district has 50 plots
var districts = districtNames.map(function(districtName) {
  var plots = [];
  for (var i = 1; i <= 50; i++) {
    // This assumes you have variables named: amritsar1, amritsar2, ..., amritsar50, etc.
    var plotVarName = districtName + i;
    plots.push(eval(plotVarName));
  }
  
  return {
    name: districtName,
    plots: plots
  };
});

print('Number of districts to process:', districts.length);

// ============== 1) Build median Sentinel-2 and compute indices ==============
var bandList = ['B1','B2','B3','B4','B5','B6','B7','B8','B8A','B9','B11','B12'];

var stateFilter = ee.FeatureCollection('FAO/GAUL/2015/level1')
  .filter(ee.Filter.eq('ADM0_NAME', countryName));

var s2col = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
  .filterDate(startDate, endDate)
  .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', cloudPct))
  .filterBounds(stateFilter.geometry());

var s2Median = s2col.median().select(bandList).toFloat();

// Compute indices
var ndvi = s2Median.normalizedDifference(['B8','B4']).rename('NDVI');
var savi = s2Median.expression(
  '((NIR - RED) * L) / (NIR + RED + (L * 0.5))',
  {'NIR': s2Median.select('B8'), 'RED': s2Median.select('B4'), 'L': 0.5}
).rename('SAVI');
var ndwi = s2Median.normalizedDifference(['B3','B11']).rename('NDWI');
var bsi = s2Median.expression(
  '((SWIR + RED) - (NIR + BLUE)) / ((SWIR + RED) + (NIR + BLUE))',
  {'SWIR': s2Median.select('B11'), 'RED': s2Median.select('B4'),
   'NIR': s2Median.select('B8'), 'BLUE': s2Median.select('B2')}
).rename('BSI');
var ndbi = s2Median.normalizedDifference(['B11','B8']).rename('NDBI');

var imageWithIndices = s2Median.addBands([ndvi, savi, ndwi, bsi, ndbi]).toFloat();
var allBands = imageWithIndices.bandNames();

// ============== 2) Process each district ==============
var statSuffixes = [
  {key: 'min', label: 'min'},
  {key: 'max', label: 'max'},
  {key: 'mean', label: 'mean'},
  {key: 'stdDev', label: 'stdDev'},
  {key: 'p10', label: 'p10'},
  {key: 'p25', label: 'p25'},
  {key: 'p50', label: 'p50'},
  {key: 'p75', label: 'p75'}
];

var percentileList = [10,25,50,75];
var reducers = ee.Reducer.minMax()
  .combine(ee.Reducer.mean(), '', true)
  .combine(ee.Reducer.stdDev(), '', true)
  .combine(ee.Reducer.percentile(percentileList), '', true);

// Function to process a single district
var processDistrict = function(districtInfo) {
  var districtName = districtInfo.name;
  var plots = districtInfo.plots;
  
  // Create feature collection from plots
  var plotFeatures = plots.map(function(geom, idx) {
    return ee.Feature(geom, {id: districtName + '_plot' + idx});
  });
  var plotsFC = ee.FeatureCollection(plotFeatures);
  
  // Use dissolve() instead of geometry() to avoid precision errors
  var unionGeom = plotsFC.geometry(1); // 1 meter error margin
  
  // Compute stats
  var stats = imageWithIndices.reduceRegion({
    reducer: reducers,
    geometry: unionGeom,
    scale: scale,
    maxPixels: 1e10,
    tileScale: 16,
    bestEffort: true
  });
  
  // Build features for each stat
  var makeFeatureForStat = function(statSuffix, label) {
    var statKey = statSuffix;
    var values = allBands.map(function(b) {
      b = ee.String(b);
      var key = ee.Algorithms.If(
        ee.List(['p10','p25','p50','p75']).contains(statKey),
        b.cat('_').cat(statKey),
        b.cat('_').cat(statKey)
      );
      return ee.Dictionary(stats).get(ee.String(key));
    });
    var props = ee.Dictionary.fromLists(allBands, values);
    props = props.set('stat', label)
                 .set('district', districtName)
                 .set('startDate', startDate)
                 .set('endDate', endDate);
    return ee.Feature(null, props);
  };
  
  return ee.FeatureCollection(
    ee.List(statSuffixes).map(function(s) {
      s = ee.Dictionary(s);
      return makeFeatureForStat(s.get('key'), s.get('label'));
    })
  );
};

// ============== 3) Process and export each district separately ==============
districts.forEach(function(dist) {
  var districtName = dist.name;
  var districtStats = processDistrict(dist);
  
  // Print info for this district
  print('Processing district:', districtName);
  print('  - Number of stat rows:', districtStats.size());
  
  // Export this district to its own CSV
  Export.table.toDrive({
    collection: districtStats,
    description: districtName + '_thresholds',
    folder: driveFolder,
    fileNamePrefix: districtName + '_thresholds',
    fileFormat: 'CSV'
  });
  
  print('  - Export scheduled: ' + districtName + '_thresholds.csv');
});

print('========================================');
print('All exports scheduled!');
print('Total districts processed:', districts.length);
print('Each district will have its own CSV file in folder:', driveFolder);